<template>
  <div class="update-request-type">
    <div class="field-selector mb-4">
      <!-- <v-select
        v-model="selectedField"
        :items="availableFields"
        item-title="text"
        item-value="value"
        label="Select Field to Update"
        class="mb-2"
      /> -->

      <label for="field-select">Select Field to Update</label>

      <select v-model="selectedField">
        <option v-for="field in availableFields" :value="field.value">
          {{ field.text }}
        </option>
      </select>
      
      <v-text-field
        v-model="newValue"
        :label="`New ${getFieldLabel(selectedField)} Value`"
        class="mb-2"
      />
    </div>

    <v-btn
      @click="updateFields"
      :loading="isUpdating"
      :disabled="isUpdating || !selectedField"
      color="warning"
      class="mr-2"
    >
      Update Selected Fields
    </v-btn>

    <div v-if="isUpdating" class="mt-2">
      Processing... {{ updateCount }} contacts updated
    </div>

    <div v-if="hasError" class="error-message mt-2">
      Error: {{ errorMessage }}
    </div>
  </div>
</template>

<script>
import { defineComponent, ref, computed } from 'vue';
import { updateContact } from '../utils/vgraphql';

export default defineComponent({
  name: 'FieldUpdate',
  props: {
    contacts: {
      type: Array,
      required: true
    }
  },
  setup(props) {
    const isUpdating = ref(false);
    const updateCount = ref(0);
    const hasError = ref(false);
    const errorMessage = ref('');
    const selectedField = ref('');
    const newValue = ref('');

    const availableFields = [
      { text: 'Request Type', value: 'requestType' },
      { text: 'Name', value: 'name' },
      { text: 'Email', value: 'email' },
      { text: 'Phone Number', value: 'phoneNumber' },
    
      { text: 'Status', value: 'status' },
      { text: 'Stage', value: 'stage' },
      { text: 'Location', value: 'location' }
    ];

    const getFieldLabel = (fieldValue) => {
      const field = availableFields.find(f => f.value === fieldValue);
      return field ? field.text : fieldValue;
    };

    const updateFields = async () => {
      if (!selectedField.value || !newValue.value) {
        alert('Please select a field and enter a new value');
        return;
      }

      if (!confirm(`Are you sure you want to update the ${getFieldLabel(selectedField.value)} field for all selected contacts? This action cannot be undone.`)) {
        return;
      }

      isUpdating.value = true;
      updateCount.value = 0;
      hasError.value = false;
      errorMessage.value = '';

      try {
        for (const contact of props.contacts) {
          const updatedData = {
            id: contact.id,
            [selectedField.value]: newValue.value,
            // Include essential fields that should remain unchanged
            name: contact.name,
            project: contact.project
          };

          await updateContact(updatedData);
          updateCount.value++;
        }

        alert(`Successfully updated ${updateCount.value} contacts`);
        // Reset form after successful update
        selectedField.value = '';
        newValue.value = '';
      } catch (error) {
        hasError.value = true;
        errorMessage.value = error.message;
        console.error('Error updating fields:', error);
      } finally {
        isUpdating.value = false;
      }
    };

    return {
      isUpdating,
      updateCount,
      hasError,
      errorMessage,
      selectedField,
      newValue,
      availableFields,
      updateFields,
      getFieldLabel
    };
  }
});
</script>

<style scoped>
.update-request-type {
  display: inline-block;
  max-width: 400px;
}

.error-message {
  color: #ff0000;
  font-weight: bold;
}

.field-selector {
  border: 1px solid #e0e0e0;
  padding: 1rem;
  border-radius: 4px;
}

select {
  width: 100%;
  padding: 8px;
  font-size: 16px;
  border: 2px solid #4CAF50;
  border-radius: 5px;
  background-color: #f9f9f9;
  color: #333;
  cursor: pointer;
  outline: none;
}

/* Style the dropdown when hovered */
select:hover {
  border-color: #45a049;
}

/* Style the dropdown when focused */
select:focus {
  border-color: #007BFF;
  box-shadow: 0 0 5px rgba(0, 123, 255, 0.5);
}

/* Style individual options */
option {
  padding: 10px;
  background-color: #fff;
  color: #333;
}

/* Style option on hover */
option:hover {
  background-color: #f1f1f1;
}

/* Optional: Style selected option */
select option:checked {
  background-color: #4CAF50;
  color: white;
}
</style>