import { defineStore } from 'pinia';

export const useUserStore = defineStore('user', {
  state: () => ({
    username: '',
    isLoggedIn: false,
  }),
  actions: {
    setUser(username) {
      this.username = username;
      this.isLoggedIn = true;
    },
    clearUser() {
      this.username = '';
      this.isLoggedIn = false;
    },
  },
});