<template>
  <v-dialog v-model="internalDialogVisible" persistent max-width="390" class="top-dialog">
    <v-card>
      <v-card-title>Enter Call Status</v-card-title>
      <v-card-text>
        <textarea v-model="internalInteraction_" placeholder="Interaction" class="e-input bordered-input" rows="3">
        </textarea>
      </v-card-text>
      <v-card-actions class="d-flex justify-space-between">
        <v-container class="pa-0">
          <v-row>
            <v-col cols="4">

              <v-btn text class="bordered-btn" @click="selectStatus('cbr')">CBR</v-btn>
            </v-col>
            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="selectStatus('dnc')">DNC</v-btn>
            </v-col>
            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="selectStatus('eg')">EG</v-btn>
            </v-col>
          </v-row>
          <v-row>
            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="selectStatus('fp')">FP</v-btn>
            </v-col>
            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="selectStatus('flp')">FLP</v-btn>
            </v-col>
         
          </v-row>
          <v-row>
            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="selectStatus('ni')">NI</v-btn>
            </v-col>
            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="selectStatus('nis')">NIS</v-btn>
            </v-col>
            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="selectStatus('wnb')">WNB</v-btn>
            </v-col>
          </v-row>
          <v-row>
            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="selectStatus('nr')">NR</v-btn>
            </v-col>
            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="selectStatus('qlf')">QLF</v-btn>
            </v-col>
            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="selectStatus('so')">SO</v-btn>
            </v-col>
          </v-row>
          <v-row>
            
            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="selectStatus('tnt')">TNT</v-btn>
            </v-col>

            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="selectStatus('vcm')">VCM</v-btn>
            </v-col>
            
            <v-col cols="4">
              <v-btn text color="red" class="bordered-btn" @click="closeDialog">Cancel</v-btn>
            </v-col>
          </v-row>
          <v-row>
            <v-col cols="12">
              <v-btn color="primary" class="bordered-btn confirm-btn" @click="confirmSave"
                :disabled="isConfirmDisabled">
                Confirm
              </v-btn>
            </v-col>
          </v-row>
        </v-container>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script>
import { ref, watch, defineComponent, computed } from 'vue';

export default defineComponent({
  name: 'statusDialog',
  props: {
    showDialog: {
      type: Boolean,
      required: true
    },
    selectedStatus: {
      type: String,
      default: ''
    },
    interaction: {
      type: String,
      default: ''
    },
    rating: {
      type: Number,
      default: 0
    }
  },
  emits: ['update:showDialog', 'updateStatus'],
  setup(props, { emit }) {
    const internalDialogVisible = ref(props.showDialog);
    const internalSelectedStatus = ref(props.selectedStatus);
    const internalSelectedStatus_ = ref("");
    const internalInteraction = ref(props.interaction);
    const internalInteraction_ = ref("");
    const internalRating = ref(props.rating);



    const statusOptions = ['cbr', 'dnc', 'eg', 'fp', 'flp', 'vcm', 'ni', 'nis', 'wnb', 'nr', 'qlf', 'so', 'tnt'];

    // Computed property for button disabled state
    const isConfirmDisabled = computed(() => {
      const disabled = !internalSelectedStatus.value || internalSelectedStatus.value.trim() === '';
      console.log('isConfirmDisabled:', disabled, 'internalSelectedStatus:', internalSelectedStatus.value);
      return disabled;
    });

    // Watch for prop changes and sync with internal state
    watch(() => props.showDialog, (newVal) => {
      internalDialogVisible.value = newVal;
      if (newVal) {
        internalSelectedStatus.value = ''; // Reset on open
      }
    });

    watch(() => props.interaction, (newVal) => {
      internalInteraction.value = newVal;
    });

    watch(() => props.rating, (newVal) => {
      internalRating.value = newVal;
    });

    watch(() => props.selectedStatus, (newVal) => {
      internalSelectedStatus.value = newVal;
    });

    watch(internalDialogVisible, (newVal) => {
      emit('update:showDialog', newVal);
    });

    // Debug watcher for internalSelectedStatus
    watch(() => internalSelectedStatus.value, (newVal) => {
      console.log('internalSelectedStatus changed to:', newVal);
    });

    const statusMapping = {
      "cbr": { rating: null, interaction: "" },
      "dnc": { rating: -1, interaction: "Do not call" },
      "eg": { rating: null, interaction: "" },
      "fp": { rating: 2, interaction: "future" },
      "flp": { rating: 3, interaction: "follow up" },
      "vcm": { rating: null, interaction: "" },
      "ni": { rating: -1, interaction: "not interested" },
      "nis": { rating: null, interaction: "" },
      "nr": { rating: null, interaction: "" },
      "qlf": { rating: 4, interaction: "qualify" },
      "so": { rating: null, interaction: "" },
      "tnt": { rating: 2, interaction: "tenanted" },
      "wnb": { rating: -1, interaction: "Wrong Number" },
    };

    const selectStatus = (cm) => {
      const status = statusMapping[cm];
      if (status) {
        internalSelectedStatus.value = cm;
        console.log('Selected status:', internalSelectedStatus.value);

        if (status.rating !== null) {
          internalRating.value = status.rating;
        }

      
          internalInteraction_.value = status.interaction;
       
      } else {
        alert(`Error# 156 unknown selection [${cm}]`);
      }
    };

  const confirmSave = () => {
  if (!internalSelectedStatus.value) return;

  const now = new Date();
  const formattedDateTime = `(${now.getDate()}/${now.getMonth() + 1} ${((now.getHours() % 12) || 12)}${now.getHours() >= 12 ? 'P' : 'A'}) `;

  if (internalInteraction_.value && internalInteraction_.value.trim() !== "" && !internalInteraction_.value.endsWith(".")) {
    internalInteraction_.value += ".";
  }

  let interactionToEmit;
  if (internalInteraction_.value && internalInteraction_.value.trim() !== "") {
    interactionToEmit = `${formattedDateTime}${internalInteraction_.value} \n${internalInteraction.value}`.trim();
  } else {
    interactionToEmit = internalInteraction.value;
  }

  emit(
    'updateStatus',
    internalSelectedStatus.value, // Corrected line
    interactionToEmit
  );

  closeDialog();
};

    const closeDialog = () => {
      internalDialogVisible.value = false;
    };

    return {
      internalDialogVisible,
      internalSelectedStatus,
      internalSelectedStatus_,
      internalInteraction,
      internalInteraction_,
      internalRating,
      statusOptions,
      selectStatus,
      confirmSave,
      closeDialog,
      isConfirmDisabled
    };
  }
});
</script>

<style scoped>
.bordered-input {
  border: 1px solid #ccc;
  border-radius: 5px;
  padding: 8px;
  width: 100%;
  box-sizing: border-box;
  resize: vertical;
  font-family: inherit;
  font-size: inherit;
}

.bordered-input:hover {
  border-color: #1976d2;
}

.bordered-input:focus {
  border-color: #1976d2;
  outline: none;
  box-shadow: 0 0 4px #1976d2;
}

.bordered-btn {
  border: 1px solid #ccc !important;
  border-radius: 5px;
  padding: 8px;
  background-color: transparent;
}

.bordered-btn:hover {
  border-color: #1976d2 !important;
}

.confirm-btn {
  width: 100%;
  margin-top: 8px;
}

.top-dialog {
  margin-top: 0 !important;
}

.top-dialog .v-dialog {
  margin-top: 0 !important;
  position: fixed !important;
  top: 160px !important;
}
</style>