<template>
  <EditContactForm :index="selectedIndex" :contacts="contacts" :on-save="saveContact" :nextContact="nextValidContact"
    :on-cancel="cancelEdit" :selectedUser="selectedUser" :selectedPhoneId="selectedPhoneId" v-show="currentContact"
    :contact="currentContact" :on-delete="confirmDelete" />

  <div class="filter-label">Filter by Contact Type:</div>

  <div v-if="currentContact == null" class="contact-list">
    <p>Project Filter: {{ projectFilter }}</p>
    <p>Rating Filter >=: {{ ratingFilter }}</p>
    <h2>Contact List</h2>

    <div class="filter-buttons">
      <v-btn @click="loadData()" color="primary" class="mr-2">Load Data</v-btn>
      <v-btn @click="showAddDialog" color="secondary" class="mr-2">Add Rent Rec</v-btn>
      <RequestTypeUpdate :contacts="contacts" :disabled="true" :key="componentKey" />
      <component :is="RequestTypeUpdate" :key="componentKey" :contacts="contacts" :disabled="true" />
      <v-btn v-for="(value, type) in activeFilters" :key="type" @click="toggleContactType(type)"
        :class="getButtonClass(type)" class="mx-1">
        {{ type }}
      </v-btn>
      <v-btn @click="toggleLeaseFromFilter"
        :class="{ 'active': showContactFromOnly, 'lease-from-active': showContactFromOnly }" color="accent"
        class="ml-2">
        Lease From {{ showContactFromOnly ? 'Only' : 'All' }}
      </v-btn>
      <v-text-field v-model="interactionFilterValue" placeholder="Enter interaction text" outlined dense
        class="mt-4 ml-4" style="max-width: 300px;"></v-text-field>
      <v-btn @click="printToPDF" color="success" class="ml-2">
        Print to PDF
      </v-btn>
    </div>

    <div v-if="dataLoaded" class="record-count">
      Total Records Retrieved: {{ contacts.length }}
    </div>
    <p v-if="!loading && sortedContacts.length > 0">Records Listed: {{ sortedContacts.length }}</p>
    <p v-if="loading">Loading...</p>
    <p v-if="!loading && sortedContacts.length === 0">No contacts found.</p>

    <v-data-table v-if="!loading && sortedContacts.length > 0" :headers="headers" :items="sortedContacts"
      :items-per-page="50" :sort-by="sortBy" :sort-desc="sortDesc" multi-sort class="elevation-5 mt-4 styled-table"
      :footer-props="{
        'items-per-page-options': [10, 25, 50, 100],
        'items-per-page-text': 'Rows per page:',
      }" @update:sort-by="updateSort" ref="dataTable">
      <template v-slot:item="{ item, index }">
        <tr>
          <td class="no-padding" width="30">
            <v-btn width="5" text @click="dialPhone(item, index)">
              {{ item.no }}
            </v-btn>
          </td>
          <td>{{ item.id }}</td>
          <td>{{ item.project }}</td>
          <td>{{ item.requestType }}</td>
          <td>{{ item.rating }}</td>
          <td>{{ item.status }}</td>
          <td>{{ item.name }}</td>
          <td>{{ item.phoneNumber }}</td>
          <td>{{ item.dialedDate }}</td>
          <td>{{ item.location }}</td>
          <td>{{ item.address }}</td>
          <td>{{ item.leaseFrom }}</td>
          <td>{{ item.leaseTo }}</td>
          <td>{{ calculateMonthsPassed(item.leaseFrom).toFixed(1) }} months</td>
          <td>{{ item.interaction }}</td>
          <td>
            <v-btn @click="recordView(item.id)" color="primary" small class="mr-2 action-button">View</v-btn>
            <v-btn @click="editView(item)" color="secondary" small class="action-button">Edit</v-btn>
          </td>
        </tr>
      </template>
    </v-data-table>

    <CardDetailsDialog v-if="isSaveDialogVisible" :isSaveDialogVisible="isSaveDialogVisible"
      :selectedCard="selectedCard" :taskMode="taskMode" @close-dialog="closeDialog" @save-changes="handleSaveChanges" />
    <AddTaskDialog :visible="isAddDialogVisible" :requestType="'rent'" @close="closeAddDialog" @save="saveDialog" />
    <ProjectSelectionDialog :visible="showProjectDialog" @close="showProjectDialog = false"
      @select-data="handleProjectSelect" />
  </div>
</template>

<script>
import { defineComponent, ref, computed, onMounted, onUnmounted } from 'vue';
import { useRouter } from 'vue-router';
import { handleAddRecord, loadByProject } from '../utils/vgraphql';
import { updateContact2 } from '../utils/contactUtils';
import CardDetailsDialog from './cardDetailsDialog.vue';
import AddTaskDialog from './AddTaskDialog.vue';
import ProjectSelectionDialog from './projectSelectionDialog.vue';
import RequestTypeUpdate from './RequestTypeUpdate.vue';
import html2canvas from 'html2canvas';
import jsPDF from 'jspdf';
import EditContactForm from "@/components/EditContactForm.vue";
import { useUserStore } from '@/stores/user';
import { isPhoneDisabled } from '../utils/contactUtils.js';

// IndexedDB setup
const DB_NAME = 'ContactDB';
const DB_VERSION = 1;
const STORE_NAME = 'contacts';

async function initDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = () => {
      console.error('Failed to open IndexedDB:', request.error);
      reject(request.error);
    };
    request.onsuccess = () => {
      console.log('IndexedDB opened successfully');
      resolve(request.result);
    };

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      console.log('Creating object store');
      db.createObjectStore(STORE_NAME, { keyPath: 'id' });
    };
  });
}

// Helper function to parse DD/MM/YYYY dates
function parseDate(dateStr) {
  if (!dateStr || typeof dateStr !== 'string') return null;
  const parts = dateStr.split('/');
  if (parts.length === 3) {
    const [day, month, year] = parts.map(Number);
    if (!isNaN(day) && !isNaN(month) && !isNaN(year) &&
      day >= 1 && day <= 31 && month >= 1 && month <= 12 && year >= 1900) {
      return new Date(year, month - 1, day).toISOString();
    }
  }
  try {
    const date = new Date(dateStr);
    return isNaN(date.getTime()) ? null : date.toISOString();
  } catch (error) {
    console.error(`Failed to parse date: ${dateStr}`, error);
    return null;
  }
}

function cleanContactData(contact) {
  // Ensure task is a plain object
  const cleanTask = contact.task
    ? {
      time: Number(contact.task.time) || 0,
      blocks: Array.isArray(contact.task.blocks) ? contact.task.blocks.map(String) : [],
      version: String(contact.task.version || '')
    }
    : { time: 0, blocks: [], version: '' };

  return {
    id: String(contact.id || ''),
    location: String(contact.location || ''),
    coBroked: contact.coBroked || null,
    coBrokedIcon: String(contact.coBrokedIcon || ''),
    no: Number(contact.no) || 0,
    user: String(contact.user || ''),
    assignee: String(contact.assignee || ''),
    name: String(contact.name || ''),
    phoneNumber: String(contact.phoneNumber || ''),
    project: String(contact.project || ''),
    occupation: String(contact.occupation || ''),
    status: String(contact.status || ''),
    phoneId: String(contact.phoneId || ''),
    interaction: String(contact.interaction || ''),
    lastCall: parseDate(contact.lastCall) || null,
    nextCall: parseDate(contact.nextCall) || null,
    called: Number(contact.called) || 0,
    rating: Number(contact.rating) || 0,
    dialedDate: parseDate(contact.dialedDate) || null,
    sourceDate: parseDate(contact.sourceDate) || null,
    contacted: Number(contact.contacted) || 0,
    language: String(contact.language || ''),
    message: String(contact.message || ''),
    doc: String(contact.doc || ''),
    source: String(contact.source || ''),
    requestType: String(contact.requestType || ''),
    requestColor: String(contact.requestColor || ''),
    process: String(contact.process || ''),
    stage: String(contact.stage || ''),
    stageEmoji: String(contact.stageEmoji || ''),
    task: cleanTask, // Use cleaned task object
    delegate: String(contact.delegate || ''),
    address: String(contact.address || ''),
    advUrl: String(contact.advUrl || ''),
    advUrlDate: parseDate(contact.advUrlDate) || null,
    facebookUrl: String(contact.facebookUrl || ''),
    notionUrl: String(contact.notionUrl || ''),
    actions: Array.isArray(contact.actions) ? contact.actions.map(String) : [],
    documents: Array.isArray(contact.documents) ? contact.documents.map(String) : [],
    advertisements: Array.isArray(contact.advertisements) ? contact.advertisements.map(String) : [],
    edit: Boolean(contact.edit),
    editField: String(contact.editField || ''),
    updatedAt: parseDate(contact.updatedAt) || null,
    info: String(contact.info || ''),
    remark: String(contact.remark || ''),
    leaseFrom: parseDate(contact.leaseFrom) || null,
    leaseTo: parseDate(contact.leaseTo) || null,
    monthlyRental: contact.monthlyRental !== null && !isNaN(Number(contact.monthlyRental)) ? Number(contact.monthlyRental) : null,
    builtUpArea: contact.builtUpArea !== null && !isNaN(Number(contact.builtUpArea)) ? Number(contact.builtUpArea) : null,
    landArea: contact.landArea !== null && !isNaN(Number(contact.landArea)) ? Number(contact.landArea) : null,
    dealCount: contact.dealCount !== null && !isNaN(Number(contact.dealCount)) ? Number(contact.dealCount) : null,
    dateBuilt: parseDate(contact.dateBuilt) || null,
    brickzPrice: contact.brickzPrice !== null && !isNaN(Number(contact.brickzPrice)) ? Number(contact.brickzPrice) : null,
    askingPrice: contact.askingPrice !== null && !isNaN(Number(contact.askingPrice)) ? Number(contact.askingPrice) : null,
    marketPrice: contact.marketPrice !== null && !isNaN(Number(contact.marketPrice)) ? Number(contact.marketPrice) : null,
    bankerEvaluation: contact.bankerEvaluation !== null && !isNaN(Number(contact.bankerEvaluation)) ? Number(contact.bankerEvaluation) : null,
    carPark: contact.carPark !== null && !isNaN(Number(contact.carPark)) ? Number(contact.carPark) : null
  };
}

async function saveToDB(db, contacts) {
  return new Promise((resolve, reject) => {
    if (!db) {
      console.error('Database not initialized');
      reject(new Error('Database not initialized'));
      return;
    }

    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);

    // Deep clone contacts to remove Vue reactivity
    const plainContacts = JSON.parse(JSON.stringify(contacts));

    const cleanedContacts = plainContacts.map(contact => {
      try {
        return cleanContactData(contact);
      } catch (error) {
        console.error('Error cleaning contact:', contact, error);
        return null;
      }
    }).filter(contact => contact !== null);

    console.log('Saving contacts to IndexedDB:', cleanedContacts.length);
    console.log('Sample cleaned contact:', cleanedContacts[0]);

    cleanedContacts.forEach(contact => {
      try {
        store.put(contact);
      } catch (error) {
        console.error('Error putting contact:', contact, error);
        reject(error);
        return;
      }
    });

    transaction.oncomplete = () => {
      console.log('Transaction completed successfully');
      resolve();
    };
    transaction.onerror = () => {
      console.error('Transaction failed:', transaction.error);
      reject(transaction.error);
    };
  });
}


async function loadFromDB(db) {
  return new Promise((resolve, reject) => {
    if (!db) {
      console.error('Database not initialized for loading');
      reject(new Error('Database not initialized'));
      return;
    }

    const transaction = db.transaction([STORE_NAME], 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => {
      console.log('Loaded contacts from IndexedDB:', request.result);
      resolve(request.result);
    };
    request.onerror = () => {
      console.error('Failed to load contacts from IndexedDB:', request.error);
      reject(request.error);
    };
  });
}

async function clearDB(db) {
  return new Promise((resolve, reject) => {
    if (!db) {
      reject(new Error('Database not initialized'));
      return;
    }
    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.clear();

    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

export default defineComponent({
  name: 'ContactList',
  components: {
    CardDetailsDialog,
    AddTaskDialog,
    ProjectSelectionDialog,
    RequestTypeUpdate,
    EditContactForm
  },
  setup() {
    const userStore = useUserStore();
    const db = ref(null);
    const showEditForm = ref(true);
    const selectedContact = ref(null);
    const selectedIndex = ref(-1);
    const componentKey = ref(0);
    const selectedContactType = ref('all');
    const contacts = ref([]);
    const loading = ref(false);
    const router = useRouter();
    const sortBy = ref(['rating']);
    const sortDesc = ref([true]);
    const interactionFilterValue = ref('');
    const isSaveDialogVisible = ref(false);
    const taskMode = ref('all');
    const selectedCard = ref(null);
    const projectFilter = ref('all');
    const locationFilter = ref('all');
    const dialedDateFilter = ref('null');
    const ratingFilter = ref(4);
    const isAddDialogVisible = ref(false);
    const showContactFromOnly = ref(false);
    const dataLoaded = ref(false);
    const showProjectDialog = ref(false);
    const currentContact = ref(null);
    const tempContacts = ref([]);
    const activeFilters = ref({
      all: false,
      rent: false,
      seller: false,
      owner: false,
      lease: false,
      tenanted: false,
      Lease_Expiry: false,
      buyer: false,
      project_buyer: false,
      project_seller: false,
    });

    const headers = [
      { text: 'ID', title: 'ID', value: 'id', sortable: true },
      { text: 'No', title: 'No', value: 'no', sortable: true },
      { text: 'Project', title: 'Project', value: 'project', sortable: true },
      { text: 'Request Type', title: 'Request Type', value: 'requestType', sortable: true },
      { text: 'Rating', title: 'Rating', value: 'rating', sortable: true },
      { text: 'Status', title: 'Status', value: 'status', sortable: true },
      { text: 'Name', title: 'Name', value: 'name', sortable: true },
      { text: 'Phone Number', title: 'Phone Number', value: 'phoneNumber', sortable: true },
      { text: 'Dialed Date', title: 'Dialed Date', value: 'dialedDate', sortable: true },
      { text: 'Location', title: 'Location', value: 'location', sortable: true },
      { text: 'Address', title: 'Address', value: 'address', sortable: true },
      { text: 'Lease From', title: 'Lease From', value: 'contactFrom', align: 'center', sortable: true },
      { text: 'Lease To', title: 'Lease To', value: 'contactTo', align: 'center', sortable: true },
      { text: 'Months Passed', title: 'Months Passed', value: 'monthsPassed', align: 'center', sortable: true },
      { text: 'Interaction', title: 'Integration', value: 'interaction', sortable: true },
      { text: 'Actions', title: 'Action', value: 'actions', sortable: false },
    ];

    onMounted(async () => {
      try {
        console.log('Component mounted, initializing DB');
        db.value = await initDB();
        const storedContacts = await loadFromDB(db.value);
        console.log('Stored contacts retrieved:', storedContacts);
        if (storedContacts && storedContacts.length > 0) {
          contacts.value = [...storedContacts]; // Spread to ensure reactivity
          dataLoaded.value = true;
          console.log('Contacts loaded into component:', contacts.value);
        } else {
          console.log('No contacts found in IndexedDB');
        }
      } catch (error) {
        console.error('Error during mount:', error);
      }
    });

    const dialPhone = (item, index) => {
      selectedContact.value = item;
      selectedIndex.value = index;
      if (selectedContact.value) {
        currentContact.value = { ...selectedContact.value };
      }
    };

    const cancelEdit = () => {
      currentContact.value = null;
    };

    const updateSort = (value) => {
      sortBy.value = value;
    };

    const showAddDialog = () => {
      isAddDialogVisible.value = true;
    };

    const handleSaveChanges = async (updatedData) => {
      const index = contacts.value.findIndex(card => card.id === updatedData.id);
      if (index !== -1) {
        contacts.value[index] = updatedData;
        try {
          await saveToDB(db.value, contacts.value);
          console.log('Contacts saved after update');
        } catch (error) {
          console.error('Error saving to IndexedDB:', error);
        }
      }
    };

    const nextValidContact = () => {
      if (selectedIndex.value < contacts.value.length - 1) {
        selectedIndex.value += 1;
      } else {
        alert("Reach end of file, start from beginning again");
        selectedIndex.value = 0;
      }
      currentContact.value = contacts.value[selectedIndex.value];
      if (isPhoneDisabled(currentContact.value)) {
        nextValidContact();
      }
    };

    // async function updateContact(id, data) {
    //   // Assuming this uses fetch or axios to update Strapi
    //   const response = await fetch(`https://sp412b-763ef468411d.herokuapp.com/api/contacts/${id}`, {
    //     method: 'PUT',
    //     headers: { 'Content-Type': 'application/json' },
    //     body: JSON.stringify({ data }) // Strapi expects { data: {...} }
    //   });
    //   if (!response.ok) throw new Error('Failed to update contact in Strapi');
    //   const updatedContact = await response.json();
    //   return updatedContact.data; // Adjust based on Strapi response structure
    // }

    // In listView.vue
    
    const saveContact = async (updatedData) => {
      loading.value = true;
      console.log('Before saveContact, contacts:', contacts.value.map(c => ({ id: c.id, name: c.name || 'no-name' })));
      try {
        let updatedContact;

        if (currentContact.value && currentContact.value.id) {
          console.log('Calling updateContact2 with id:', currentContact.value.id, 'data:', updatedData);
          updatedContact = await updateContact2(currentContact.value.id, updatedData);
          console.log('Received from updateContact2:', updatedContact);
          if (!updatedContact || !updatedContact.id) {
            throw new Error('updateContact2 returned invalid data');
          }
          const index = contacts.value.findIndex(c => c.id === updatedContact.id);
          if (index !== -1) {
            contacts.value[index] = { ...updatedContact };
            console.log('Updated contact in array:', contacts.value[index]);
          } else {
            console.warn('Contact not found, adding:', updatedContact.id);
            contacts.value.push({ ...updatedContact });
            console.log('Added contact to array:', contacts.value[contacts.value.length - 1]);
          }
        } else {
          console.log('Calling createContact with data:', updatedData);
          updatedContact = await createContact(updatedData);
          console.log('Received from createContact:', updatedContact);
          if (!updatedContact || !updatedContact.id) {
            throw new Error('createContact returned invalid data');
          }
          const exists = contacts.value.some(c => c.id === updatedContact.id);
          if (!exists) {
            contacts.value.push({ ...updatedContact });
            console.log('Added new contact:', updatedContact);
          } else {
            console.warn('Duplicate ID detected, updating instead:', updatedContact.id);
            const index = contacts.value.findIndex(c => c.id === updatedContact.id);
            contacts.value[index] = { ...updatedContact };
            console.log('Updated duplicate contact:', contacts.value[index]);
          }
        }

        console.log('After saveContact, contacts:', contacts.value.map(c => ({ id: c.id, name: c.name || 'no-name' })));
        await saveToDB(db.value, contacts.value);
        console.log('IndexedDB updated successfully');
        currentContact.value = null;
      } catch (error) {
        console.error('Error in saveContact:', error);
        alert('Failed to save contact: ' + error.message);
      } finally {
        loading.value = false;
      }
    };

    const toggleContactType = async (type) => {
      if (selectedContactType.value === type) {
        selectedContactType.value = 'all';
        for (let key in activeFilters.value) {
          activeFilters.value[key] = false;
        }
      } else {
        selectedContactType.value = type;
        for (let key in activeFilters.value) {
          activeFilters.value[key] = key === type;
        }
      }
      showContactFromOnly.value = false;
      await fetchContactsByType(selectedContactType.value);
    };

    const toggleLeaseFromFilter = async () => {
      showContactFromOnly.value = !showContactFromOnly.value;
      if (showContactFromOnly.value) {
        for (let key in activeFilters.value) {
          activeFilters.value[key] = false;
        }
        selectedContactType.value = 'all';
      }
    };

    const fetchContactsByType = async (type) => {
      try {
        loading.value = true;
        const filter = type !== 'all' ? { requestType: { eq: type } } : {};
        if (showContactFromOnly.value) {
          filter.leaseFrom = { ne: null };
        }
        await new Promise(resolve => setTimeout(resolve, 1000));
      } catch (error) {
        console.error('Error fetching contacts:', error);
        alert('Failed to fetch contacts. Please try again.');
      } finally {
        loading.value = false;
      }
    };

    const recordView = (contactId) => {
      router.push({ name: 'recordView', params: { id: contactId } });
    };

    const editView = (contact) => {
      if (!contact || !contact.id) {
        console.error('Invalid contact object:', contact);
        alert('Error: Contact data is missing or incomplete.');
        return;
      }
      selectedCard.value = { ...contact };
      taskMode.value = contact.requestType;
      isSaveDialogVisible.value = true;
    };

    const calculateMonthsPassed = (leaseFrom) => {
      if (!leaseFrom) return 0;
      const today = new Date();
      const startDate = new Date(leaseFrom);
      let monthsPassed =
        (today.getFullYear() - startDate.getFullYear()) * 12 + (today.getMonth() - startDate.getMonth());
      if (today.getDate() < startDate.getDate()) monthsPassed--;
      return parseFloat(monthsPassed.toFixed(1));
    };

    const sortedContacts = computed(() => {
      const filteredContacts = contacts.value.filter((contact) => {
        const matchesTaskMode =
          selectedContactType.value === 'all' || contact.requestType === selectedContactType.value;
        const matchesInteraction =
          !interactionFilterValue.value || contact.interaction?.includes(interactionFilterValue.value);
        const matchesContactFrom = !showContactFromOnly.value || contact.leaseFrom != null;
        return matchesTaskMode && matchesInteraction && matchesContactFrom;
      });

      return filteredContacts.map(contact => ({
        ...contact,
        monthsPassed: calculateMonthsPassed(contact.leaseFrom)
      }));
    });

    const closeAddDialog = () => {
      isAddDialogVisible.value = false;
    };

    const saveDialog = async (data) => {
      isAddDialogVisible.value = false;
      handleAddRecord(data, contacts);
      try {
        await saveToDB(db.value, contacts.value);
        console.log('New contact saved via dialog');
      } catch (error) {
        console.error('Error saving to IndexedDB:', error);
      }
    };

    const closeDialog = async () => {
      isSaveDialogVisible.value = false;
    };

    const loadData = async () => {
      showProjectDialog.value = true;
    };


    

    const handleProjectSelect = async (data) => {
      try {
        componentKey.value++;
        loading.value = true;
        projectFilter.value = data.project;
        locationFilter.value = data.location;
        dialedDateFilter.value = data.dialedDate;
        ratingFilter.value = data.rating;

        // Clear existing IndexedDB data before loading new
        await clearDB(db.value);  // Add this line

        // Reset local contacts array
        contacts.value = [];  // Add this line

        // Load fresh data
        await loadByProject(
          projectFilter.value,
          locationFilter.value,
          dialedDateFilter.value,  // Fixed parameter
          ratingFilter.value,
          contacts
        );

        async function clearDB(db) {
          return new Promise((resolve, reject) => {
            if (!db) {
              reject(new Error('Database not initialized'));
              return;
            }
            const transaction = db.transaction([STORE_NAME], 'readwrite');
            const store = transaction.objectStore(STORE_NAME);
            const request = store.clear();

            request.onsuccess = () => resolve();
            request.onerror = () => reject(request.error);
          });
        }
        // Save only the new dataset
        await saveToDB(db.value, contacts.value);

        dataLoaded.value = true;
        showProjectDialog.value = false;
      } catch (error) {
        console.error('Error loading data:', error);
        alert('Failed to load data. Please try again.');
      } finally {
        loading.value = false;
      }
    };
    const getButtonClass = (type) => {
      return {
        'Lease_Expiry': selectedContactType.value === 'Lease_Expiry' && type === 'Lease_Expiry',
        'tenanted-active': selectedContactType.value === 'tenanted' && type === 'tenanted',
        'owner-active': selectedContactType.value === 'owner' && type === 'owner',
        'all-active': selectedContactType.value === 'all' && type === 'all',
        'rent-active': selectedContactType.value === 'rent' && type === 'rent',
        'seller-active': selectedContactType.value === 'seller' && type === 'seller',
        'lease-active': selectedContactType.value === 'lease' && type === 'lease',
        'buyer-active': selectedContactType.value === 'buyer' && type === 'buyer',
        'project-buyer-active': selectedContactType.value === 'project_buyer' && type === 'project_buyer',
        'project-seller-active': selectedContactType.value === 'project_seller' && type === 'project_seller',
      };
    };

    const printToPDF = () => {
      const actionButtons = document.querySelectorAll('.action-button');
      actionButtons.forEach(button => button.style.display = 'none');

      const table = document.querySelector('.v-data-table');
      if (table) {
        html2canvas(table).then((canvas) => {
          const imgData = canvas.toDataURL('image/png');
          const pdf = new jsPDF('p', 'mm', 'a4');
          const imgWidth = 210;
          const imgHeight = (canvas.height * imgWidth) / canvas.width;
          pdf.addImage(imgData, 'PNG', 0, 0, imgWidth, imgHeight);
          pdf.save('contact-list.pdf');
          actionButtons.forEach(button => button.style.display = '');
        });
      }
    };

    onUnmounted(() => {
      if (db.value) {
        db.value.close();
        console.log('Database closed');
      }
      console.log('ContactList component unmounted');
      componentKey.value = 0;
    });

    return {
      userStore,
      showEditForm,
      componentKey,
      contacts,
      loadData,
      selectedContactType,
      recordView,
      editView,
      fetchContactsByType,
      calculateMonthsPassed,
      loading,
      ratingFilter,
      interactionFilterValue,
      isSaveDialogVisible,
      taskMode,
      closeAddDialog,
      selectedCard,
      projectFilter,
      locationFilter,
      dialedDateFilter,
      isAddDialogVisible,
      showAddDialog,
      saveDialog,
      closeDialog,
      showContactFromOnly,
      toggleLeaseFromFilter,
      activeFilters,
      toggleContactType,
      dataLoaded,
      showProjectDialog,
      handleProjectSelect,
      headers,
      getButtonClass,
      handleSaveChanges,
      sortBy,
      sortDesc,
      updateSort,
      sortedContacts,
      printToPDF,
      dialPhone,
      currentContact,
      cancelEdit,
      selectedIndex,
      saveContact,
      nextValidContact,
    };
  },
});
</script>

