<template>
  <div>
    <button @click="openDialog" class="btn btn-open">Add New Task</button>
    <TaskDialog :visible="isDialogVisible" @close="closeDialog" @save="saveTask" />
    
    <div v-if="tasks.length" class="task-list">
      <h3>Saved Tasks</h3>
      <ul>
        <li v-for="(task, index) in tasks" :key="index">{{ task.name }} - {{ task.phoneNumber }}</li>
      </ul>
    </div>
  </div>
</template>

<script setup>
import { ref } from 'vue';
import TaskDialog from './AddTaskDialog.vue';

const isDialogVisible = ref(false);
const tasks = ref([]);

const openDialog = () => {
  isDialogVisible.value = true;
};

const closeDialog = () => {
  isDialogVisible.value = false;
};

const saveTask = (taskData) => {
  tasks.value.push(taskData);
  closeDialog();
};


</script>

<style scoped>
.btn-open {
  background-color: #007bff;
  color: white;
  padding: 10px 20px;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

.btn-open:hover {
  background-color: #0056b3;
}

.task-list {
  margin-top: 20px;
}

.task-list ul {
  list-style-type: none;
  padding: 0;
}

.task-list li {
  padding: 5px 0;
  border-bottom: 1px solid #ccc;
}
</style>
