<template>
  <div v-if="isSaveDialogVisible" class="dialog-wrapper">
    <div class="dialog-content">
      <h2>Card Details</h2>
      <button class="close-button" @click="closeDialog">X</button>

      <card-info :card="selectedCard" />

      <!-- Existing sections for Actions, Documents, and Advertisements -->

      <rental-info v-if="taskMode === 'lease' || taskMode === 'rent'" :card="selectedCard" />

      <!-- Add leaseFrom and leaseTo fields -->
      <section class="section-header">
        <h3>Lease Information</h3>
      </section>
      <div class="lease-fields">
        <label for="leaseFrom">Lease From:</label>
        <input type="date" id="leaseFrom" v-model="selectedCard.leaseFrom" />

        <label for="leaseTo">Lease To:</label>
        <input type="date" id="leaseTo" v-model="selectedCard.leaseTo" />
      </div>

      <price-evaluation v-if="taskMode === 'seller'" :card="selectedCard" />

      <div class="action-buttons">
        <button @click="handleSave" class="e-btn e-primary">💾 Save</button>
        <button @click="handleDelete" class="e-btn e-primary">X Delete</button>
        <button @click="closeDialog" class="e-btn">Close</button>
      </div>

      <cloudi-upload />
    </div>
  </div>
</template>

<script>
import { ref } from 'vue';
import CardInfo from './CardInfo.vue';
import ActionItem from './ActionItem.vue';
import DocumentItem from './DocumentItem.vue';
import AdvertisementItem from './AdvertisementItem.vue';
import RentalInfo from './RentalInfo.vue';
import PriceEvaluation from './PriceEvaluation.vue';
import CloudiUpload from './cloudiUpload.vue'; // Assuming this exists
import { updateContact, deleteContact } from "../utils/vgraphql";

export default {
  name: 'CardDetailsDialog',
  components: {
    CardInfo,
    ActionItem,
    DocumentItem,
    AdvertisementItem,
    RentalInfo,
    PriceEvaluation,
    CloudiUpload
  },
  props: {
    isSaveDialogVisible: Boolean,
    selectedCard: Object,
    taskMode: String
  },

  emits: ['close-dialog', 'save-changes'],

  setup(props, { emit }) {
    console.log('Selected Card:', props.selectedCard); // Debugging line
    const isDeleting = ref(false);

    // Methods
    const closeDialog = () => {
      emit('close-dialog');
    };

    const handleSave = async () => {
      try {
        const updatedData = {
          ...props.selectedCard
        };

        // Show confirmation dialog and save
        await new Promise((resolve) => {
          if (confirm('Are you sure you want to save these changes?')) {
            resolve();
          }
        });
        let id = updatedData.id;
        await updateContact(updatedData);
        updatedData.id = id;
        emit('save-changes', updatedData);
        console.log('Saving changes:', updatedData);
        closeDialog();
      } catch (error) {
        console.error('Error saving card:', error);
        alert('Error saving changes: ' + error.message);
      }
    };

    const handleDelete = async () => {
      console.log('Setting isDeleting to true');
      isDeleting.value = true;
      try {
        console.log('Deleting contact...');
        await deleteContact(props.selectedCard.id);
        console.log('Contact deleted successfully');
        emit('close-dialog'); // Ensure the parent updates isSaveDialogVisible
      } catch (error) {
        console.error('Error deleting contact:', error);
      } finally {
        console.log('Setting isDeleting to false');
        isDeleting.value = false;
      }
    };

    const addAction = () => {
      if (!props.selectedCard.action) props.selectedCard.action = [];
      props.selectedCard.action.push({ task: "", date: "", status: "" });
    };

    const addDocument = () => {
      if (!props.selectedCard.document) props.selectedCard.document = [];
      props.selectedCard.document.push({ description: "", url: "" });
    };

    const addAdvertisement = () => {
      if (!props.selectedCard.advertisement) props.selectedCard.advertisement = [];
      props.selectedCard.advertisement.push({ advertiser: "", url: "", date: "" });
    };

    const removeAction = (index) => {
      if (props.selectedCard.action && props.selectedCard.action.length > index) {
        props.selectedCard.action.splice(index, 1);
      }
    };

    const removeDocument = (index) => {
      if (props.selectedCard.document && props.selectedCard.document.length > index) {
        props.selectedCard.document.splice(index, 1);
      }
    };

    const removeAdvertisement = (index) => {
      if (props.selectedCard.advertisement && props.selectedCard.advertisement.length > index) {
        props.selectedCard.advertisement.splice(index, 1);
      }
    };

    return {
      closeDialog, handleSave, handleDelete, addAction, addDocument, addAdvertisement, removeAction, removeDocument, removeAdvertisement
    };
  }
};
</script>

<style scoped>
.dialog-wrapper {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  justify-content: center;
  align-items: center;
}

.dialog-content {
  background: white;
  padding: 20px;
  width: 100%;
  height: 100%;
  overflow-y: auto;
  position: relative;
}

.close-button {
  position: absolute;
  top: 10px;
  right: 10px;
  background: none;
  border: none;
  font-size: 20px;
  cursor: pointer;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0;
}

.action-buttons {
  display: flex;
  justify-content: space-around;
  align-items: center;
  margin-top: 10px;
}

.nice-button {
  padding: 8px 12px;
  background-color: #4CAF50;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

.nice-button:hover {
  background-color: #45a049;
}

.e-btn {
  padding: 8px 12px;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  margin: 0 5px;
}

.e-btn.e-primary {
  background-color: #007bff;
  color: white;
}

.e-btn:hover {
  background-color: #e0e0e0;
}

.lease-fields {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 20px;
}

.lease-fields label {
  font-weight: bold;
}

.lease-fields input {
  padding: 8px;
  border: 1px solid #ccc;
  border-radius: 4px;
}
</style>