<template>
  <div class="dialing-performance">
    <div>
      <v-select v-model="selectedYear" :items="years" label="Year" @update:modelValue="fetchDialingData" class="ma-2"></v-select>

      <v-select v-model="selectedMonth"
        :items="[{ value: '', text: 'All' }, ...months.map(m => ({ value: m.value, text: m.label }))]" item-title="text"
        item-value="value" label="Month" @update:modelValue="fetchDialingData" class="ma-2"></v-select>

      <v-select v-model="selectedProject"
        :items="[{ value: '', text: 'All' }, ...projects.map(p => ({ value: p, text: p }))]" item-title="text"
        item-value="value" label="Project" @update:modelValue="fetchDialingData" class="ma-2"></v-select>

      <v-checkbox v-model="showAssignee" label="Show Assignee" class="ma-2"></v-checkbox>

      <v-btn @click="fetchDialingData" color="success" class="ma-2">Load</v-btn>
      <v-btn @click="printPDF" color="primary" class="ma-2">Print PDF</v-btn>
    </div>

    <v-alert v-if="loading" type="info" class="mb-4">Loading dialing data...</v-alert>
    <v-alert v-else-if="error" type="error" class="mb-4">{{ error }}</v-alert>
    <div v-else>
      <h1>KPI</h1>
      <p>Total Dials: {{ totalDials }}</p>
      <p>Total Records Retrieved: {{ totalRecords }}</p>
      <p>Total Records Fetched: {{ totalRecordsFetch }}</p>
      <v-data-table :headers="headers" :items="tableItems" dense :footer-props="{
        itemsPerPageOptions: [0],
        showFirstLastPage: false,
        disablePagination: true,
        itemsPerPageText: 'Total:'
      }">
        <template v-slot:header="{ props: { headers } }">
          {{ console.log('headers array:', headers) }}
          <tr>
            <th v-for="header in headers" :key="header.value" @click="showColumnName(header.title)" class="clickable-header">
              {{ header.title }}
            </th>
          </tr>
        </template>

        <template v-slot:header.project>
          <button @click="console.log('you have clicked me')">Project</button>
        </template>
        <template v-slot:header.unsuccessful>
          <button @click="showDetailedRecords('unsuccessful')">Unsuccessful</button>
        </template>
        <template v-slot:header.future>
          <button @click="showDetailedRecords('future')">Future</button>
        </template>
        <template v-slot:header.followUp>
          <button @click="showDetailedRecords('followUp')">Follow Up</button>
        </template>
        <template v-slot:header.converting>
          <button @click="showDetailedRecords('converting')">Converting</button>
        </template>
        <template v-slot:header.converted>
          <button @click="showDetailedRecords('converted')">Converted</button>
        </template>

        <template v-slot:item.date="{ item }">
          <span :rowspan="Object.keys(item.projects).length">{{ item.date }}</span>
        </template>
        <template v-slot:item.project="{ item }">
          <span>{{ item.project }}</span>
        </template>
        <template v-slot:item.assignee="{ item }">
          <span v-if="showAssignee">{{ item.assignee || 'N/A' }}</span>
        </template>
      </v-data-table>

      <!-- Custom Footer -->
      <div v-if="tableItems.length > 0">
        <table class="v-data-footer">
          <tr>
            <td v-for="(header, index) in headers" :key="index" :colspan="index === 0 ? headers.length - 7 : null">
              <span v-if="index === 0">Total:</span>
            </td>
            <td>{{ calculateTotal('totalDials', tableItems) }}</td>
            <td>{{ calculateTotal('unsuccessful', tableItems) }}</td>
            <td>{{ calculateTotal('future', tableItems) }}</td>
            <td>{{ calculateTotal('followUp', tableItems) }}</td>
            <td>{{ calculateTotal('converting', tableItems) }}</td>
            <td>{{ calculateTotal('converted', tableItems) }}</td>
            <td>{{ calculateTotal('closed', tableItems) }}</td>
          </tr>
        </table>
      </div>
    </div>
  </div>
  <v-dialog v-model="dialog" max-width="800px">
    <v-card>
      <v-card-title>
        <span class="headline">Detailed Records - {{ dialogTitle }}</span>
      </v-card-title>
      <v-card-text>
        <v-data-table :headers="detailHeaders" :items="detailedRecords" dense>
          <template v-slot:item.dialedDate="{ item }">
            {{ item.dialedDate.split('T')[0] }}
          </template>
        </v-data-table>
      </v-card-text>
      <v-card-actions>
        <v-spacer></v-spacer>
        <v-btn color="primary" text @click="dialog = false">Close</v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script>
import { gql } from '@apollo/client/core';
import client from '../apollo-client';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import { ref, computed, watch, onMounted } from 'vue';
import { formatDateForStrapi } from '../utils/vgraphql';

export default {
  name: 'DialingPerformanceList',
  setup() {
    const dialStats = ref({});
    const loading = ref(true);
    const error = ref(null);
    const selectedYear = ref(new Date().getFullYear());
    const selectedMonth = ref('');
    const selectedProject = ref('');
    const showAssignee = ref(false);
    const dialogTitle = ref('');
    const detailedRecords = ref([]);
    const dialog = ref(false);
    const rawLeads = ref([]);

    const years = Array.from({ length: 5 }, (_, i) => new Date().getFullYear() - i);
    const months = [
      { value: '01', label: 'January' },
      { value: '02', label: 'February' },
      { value: '03', label: 'March' },
      { value: '04', label: 'April' },
      { value: '05', label: 'May' },
      { value: '06', label: 'June' },
      { value: '07', label: 'July' },
      { value: '08', label: 'August' },
      { value: '09', label: 'September' },
      { value: '10', label: 'October' },
      { value: '11', label: 'November' },
      { value: '12', label: 'December' }
    ];

    const projects = [
      'BUKIT OUG CONDOMINIUM',
      'm_terra',
      'Parklane 1',
      'Parklane 2',
      'Parklane 3',
      'Parklane 4',
      'Parklane 5',
      'Sutra Embun',
      'rbj',
      'RSKU Sungai Long',
      'Parklane OUG',
      'task',
      'TMN YARL',
      'trr1082044 Eco Majestic Semenyih',
      'trr1082289 Union Heights ( Eco Sky )'
    ];

    const headers = computed(() => [
      { title: 'Date', value: 'date', sortable: false },
      { title: 'Project', value: 'project' },
      ...(showAssignee.value ? [{ title: 'Assignee', value: 'assignee', sortable: false }] : []),
      { title: 'Total Dials', value: 'totalDials' },
      { title: 'Unsuccessful', value: 'unsuccessful' },
      { title: 'Future', value: 'future' },
      { title: 'Follow Up', value: 'followUp' },
      { title: 'Converting', value: 'converting' },
      { title: 'Converted', value: 'converted' },
      { title: 'Closed', value: 'closed' }
    ]);

    const detailHeaders = [
      { title: 'Id', value: 'id' },
      { title: 'Date', value: 'dialedDate' },
      { title: 'Project', value: 'project' },
      { title: 'Interaction', value: 'interaction' },
      { title: 'Assignee', value: 'assignee' },
      { title: 'Rating', value: 'rating' },
      { title: 'Request Type', value: 'requestType' }
    ];

    const filteredDialStats = computed(() => {
      return Object.fromEntries(
        Object.entries(dialStats.value).filter(([date]) => {
          const [year, month] = date.split('-');
          return (
            year === selectedYear.value.toString() &&
            (selectedMonth.value === '' || month === selectedMonth.value)
          );
        })
      );
    });

    const totalDials = computed(() => {
      let total = 0;
      for (const projects of Object.values(filteredDialStats.value)) {
        for (const entry of Object.values(projects)) {
          total += entry.totalDials;
        }
      }
      return total;
    });

    const totalRecordsFetch = computed(() => {
      return dialStats.value.totalRecordsFetched || 0;
    });

    const totalRecords = computed(() => {
      return dialStats.value.totalRecords || 0;
    });

    const calculateTotal = (column, items) => {
      return items.reduce((total, item) => total + (item[column] || 0), 0);
    };

    const tableItems = computed(() => {
      let items = [];
      for (const [date, projects] of Object.entries(filteredDialStats.value)) {
        for (const [project, entry] of Object.entries(projects)) {
          if (selectedProject.value === '' || project === selectedProject.value) {
            items.push({
              date: new Date(date),
              project,
              assignee: showAssignee.value ? entry.assignee : undefined,
              totalDials: entry.totalDials,
              unsuccessful: entry.unsuccessful,
              future: entry.future,
              followUp: entry.followUp,
              converting: entry.converting,
              converted: entry.converted,
              closed: entry.closed,
              projects
            });
          }
        }
      }
      items.sort((a, b) => a.date - b.date);
      return items.map(item => ({ ...item, date: item.date.toISOString().split('T')[0] }));
    });

    const showColumnName = (columnName) => {
      console.log(`Clicked column: ${columnName}`);
      alert(`You clicked the column: ${columnName}`);
    };

    const showDetailedRecords = (column) => {
      console.log(`Showing detailed records for: ${column}`);
      dialogTitle.value = column.charAt(0).toUpperCase() + column.slice(1);
      let ratingFilter;

      switch (column) {
        case 'unsuccessful':
          ratingFilter = (rating) => rating === 1 || rating === 0 || rating === null;
          break;
        case 'future':
          ratingFilter = (rating) => rating === 2;
          break;
        case 'followUp':
          ratingFilter = (rating) => rating === 3;
          break;
        case 'converting':
          ratingFilter = (rating) => rating === 4;
          break;
        case 'converted':
          ratingFilter = (rating) => rating === 5;
          break;
        case 'closed':
          ratingFilter = (rating) => rating === 6;
          break;
        default:
          ratingFilter = () => false;
      }

      detailedRecords.value = rawLeads.value
        .filter(lead => {
          const rating = parseInt(lead.rating) || 0;
          const matchesProject = selectedProject.value === '' || lead.project === selectedProject.value;
          return ratingFilter(rating) && matchesProject;
        })
        .map(lead => ({
          id: lead.id,
          dialedDate: lead.dialedDate,
          project: lead.project || 'Unknown',
          assignee: lead.assignee || 'N/A',
          interaction: lead.interaction || '',
          rating: lead.rating || 'N/A',
          requestType: lead.requestType || 'N/A'
        }));

      console.log('Raw leads:', rawLeads.value);
      console.log('Filtered records:', detailedRecords.value);
      dialog.value = true;
    };

    const fetchDialingData = async () => {
      loading.value = true;
      error.value = null;

      const startDate = selectedMonth.value ? `${selectedYear.value}-${selectedMonth.value}-01` : `${selectedYear.value}-01-01`;
      const endDate = selectedMonth.value ? `${selectedMonth.value === '02' ? `${selectedYear.value}-${selectedMonth.value}-28` : `${selectedYear.value}-${selectedMonth.value}-31`}` : `${selectedYear.value}-12-31`;

      let fstartDate = formatDateForStrapi(startDate);
      let fendDate = formatDateForStrapi(endDate);

      console.log('Formatted start date:', fstartDate);
      console.log('Formatted end date:', fendDate);

      try {
        let query;
        let variables;

        if (selectedProject.value) {
          query = gql`
            query GetDials($startDate: DateTime!, $endDate: DateTime!, $project: String!) {
              leads(
                pagination: { limit: 2000 },
                sort: ["project", "dialedDate"],
                filters: { 
                  dialedDate: { 
                    gte: $startDate, 
                    lte: $endDate 
                  },
                  project: { eq: $project }
                }
              ) {
                data {
                  id
                  attributes {
                    requestType
                    dialedDate
                    interaction
                    assignee
                    project
                    rating
                  }
                }
                meta {
                  pagination {
                    total
                  }
                }
              }
            }
          `;
          variables = {
            startDate: fstartDate,
            endDate: fendDate,
            project: selectedProject.value
          };
        } else {
          query = gql`
            query GetDials($startDate: DateTime!, $endDate: DateTime!) {
              leads(
                pagination: { limit: 2000 },
                sort: ["project", "dialedDate"],
                filters: { 
                  dialedDate: { 
                    gte: $startDate, 
                    lte: $endDate 
                  }
                }
              ) {
                data {
                  id
                  attributes {
                    requestType
                    dialedDate
                    interaction
                    assignee
                    project
                    rating
                  }
                }
                meta {
                  pagination {
                    total
                  }
                }
              }
            }
          `;
          variables = {
            startDate: fstartDate,
            endDate: fendDate
          };
        }

        console.log('Query:', query.loc.source.body);
        console.log('Variables:', variables);

        const { data } = await client.query({
          query,
          variables,
          fetchPolicy: 'no-cache',
        });

        rawLeads.value = data.leads.data.map(lead => ({
          id: lead.id,
          ...lead.attributes
        }));
        console.log('Raw leads fetched:', rawLeads.value);

        dialStats.value = {
          totalRecords: data.leads.meta.pagination.total,
          totalRecordsFetched: data.leads.data.length,
          ...data.leads.data.reduce((acc, lead) => {
            let { dialedDate, project, rating, assignee } = lead.attributes;
            project = project || 'Unknown';
            assignee = assignee || 'N/A';
            rating = parseInt(rating) || 0;

            if (dialedDate) {
              let parsedDate = new Date(dialedDate);
              if (!isNaN(parsedDate)) {
                let date = parsedDate.toISOString().split('T')[0];
                acc[date] = acc[date] || {};
                acc[date][project] = acc[date][project] || {
                  assignee,
                  totalDials: 0,
                  unsuccessful: 0,
                  future: 0,
                  followUp: 0,
                  converting: 0,
                  converted: 0,
                  closed: 0
                };

                acc[date][project].totalDials += 1;

                switch (rating) {
                  case 1: acc[date][project].unsuccessful += 1; break;
                  case 2: acc[date][project].future += 1; break;
                  case 3: acc[date][project].followUp += 1; break;
                  case 4: acc[date][project].converting += 1; break;
                  case 5: acc[date][project].converted += 1; break;
                  case 6: acc[date][project].closed += 1; break;
                  default: acc[date][project].unsuccessful += 1;
                }
              }
            }
            return acc;
          }, {})
        };
      } catch (err) {
        error.value = 'Failed to load dialing data: ' + (err.message || 'Unknown error');
        console.error('Error fetching data:', err);
      } finally {
        loading.value = false;
      }
    };

    const printPDF = () => {
      const doc = new jsPDF();
      const tableColumn = [
        "Date",
        "Project",
        "Total Dials",
        "Unsuccessful",
        "Future",
        "Follow Up",
        "Converting",
        "Converted",
        "Closed"
      ];

      if (showAssignee.value) tableColumn.splice(2, 0, "Assignee");

      const tableRows = [];
      for (const item of tableItems.value) {
        const rowData = [
          item.date,
          item.project,
          ...(showAssignee.value ? [item.assignee || 'N/A'] : []),
          item.totalDials.toString(),
          item.unsuccessful.toString(),
          item.future.toString(),
          item.followUp.toString(),
          item.converting.toString(),
          item.converted.toString(),
          item.closed.toString()
        ];
        tableRows.push(rowData);
      }

      doc.autoTable({ head: [tableColumn], body: tableRows, theme: 'grid' });
      doc.save('dialing_performance.pdf');
    };

    watch([selectedYear, selectedMonth, selectedProject], fetchDialingData);
    // onMounted(fetchDialingData);

    return {
      dialStats,
      loading,
      error,
      selectedYear,
      selectedMonth,
      selectedProject,
      showAssignee,
      years,
      months,
      projects,
      filteredDialStats,
      totalDials,
      totalRecords,
      fetchDialingData,
      printPDF,
      totalRecordsFetch,
      headers,
      tableItems,
      calculateTotal,
      showColumnName,
      showDetailedRecords,
      dialogTitle,
      detailedRecords,
      dialog,
      rawLeads,
      detailHeaders
    };
  }
};
</script>

<style>
.dialing-performance {
  font-family: Arial, sans-serif;
}

.v-data-footer {
  width: 100%;
  border-top: 1px solid rgba(0, 0, 0, 0.12);
  margin-top: 8px;
}

.v-data-footer td {
  padding: 8px;
  text-align: center;
}

.clickable-header {
  cursor: pointer;
  user-select: none;
}

.clickable-header:hover {
  background-color: #f5f5f5;
}
</style>"

