import { createRouter, createWebHistory } from 'vue-router';
import counterDisp from '../components/counterDisp.vue';
import kanban from '../components/kanban.vue';
import listCards from '../components/listCards.vue';
import listPhones from '../components/listPhones.vue';
import scheduler from '../components/scheduler.vue';
import performance from '../components/performance.vue';
import listView from '../components/listView.vue';
import recordView from '../components/recordView.vue';
import testcom from '../components/testcom.vue';
import DialingPerformance from '../components/KPI.vue';

// import HelloWorld from '../components/HelloWorld.vue';

const routes = [
  { path: '/', name: 'home', component: listPhones }, 
  { path: '/kanban', name: 'kanban', component: kanban }, 
  { path: '/counterDisp', name: 'counterDisp', component: counterDisp }, 
  { path: '/listCards', name: 'listCards', component: listCards }, 
  { path: '/listPhones', name: 'listPhones', component: listPhones }, 
  { path: '/scheduler', name: 'scheduler', component: scheduler }, 
  { path: '/performance', name: 'performance', component: performance }, 
  { path: '/listView', name: 'listView', component: listView}, 
  { path: '/recordView/:id', name: 'recordView', component: recordView, props: true },
  { path: '/testcom', name: 'testcom', component: testcom },
  { path: '/DialingPerformance', name: 'DialingPerformance', component: DialingPerformance }
];

const router = createRouter({
  history: createWebHistory(), // Set the base URL here
  routes,
});

export default router;
